statement:
∀ {n d : ℕ},
  d < n →
    n * d % 2 = 0 →
      have N := d + 1;
      have M := n / N - 1;
      have r := N + n % N;
      n = M * N + r ∧ N ≤ r ∧ r < 2 * N ∧ r * d % 2 = 0

∀ {V : Type u_1} [inst : Fintype V] [inst_1 : DecidableEq V] {T : ℕ} (R : Carpooling.Run V T) (C : Finset V) {t : ℕ}
  (ht : t < T),
  Carpooling.internalCount R C (t + 1) = Carpooling.internalCount R C t + if (R.step t ht).u ∈ C then 1 else 0
